/**
 * Globals for tsconfig.samples.json only.
 *
 * Samples generated by igniteui-xplat-examples annotate render() with the
 * global JSX namespace, which @types/react 19 removed in favor of React.JSX.
 * Restore the one member they use, so the check reports real errors only.
 */
import type { JSX as ReactJSX } from 'react';

declare global {
  namespace JSX {
    type Element = ReactJSX.Element;
  }
}
